mapper.sql:
WHERE dataset_id=#{q.datasetId} AND result_version=#{q.resultVersion}


    AND station_code=#{q.filters.station} AND observation_date >= #{q.filters.from} AND observation_date < #{q.filters.to}


    AND station_code=#{q.filters.station} AND observation_year=#{q.filters.year}



      AND observation_date=#{q.filters.date}
      AND observation_year=#{q.filters.year}

    AND region_level=#{q.filters.level} AND metric=#{q.filters.metric}
    AND country=#{q.filters.country}
    AND province=#{q.filters.province}
    AND city=#{q.filters.city}
    AND district=#{q.filters.district}

mapper.select:
SELECT FROM ORDER BY
station_code observation_date metric country,province,city,district
LIMIT #{limit} OFFSET #{offset}
